mapper.select:
		select 

		from MST_YIELD_CURVE_INFO

			AND CURVE_CODE = #{curveCode,jdbcType=VARCHAR}
            AND CURVE_TYPE = #{curveType,jdbcType=VARCHAR}
            AND TO_CHAR(CURVE_DATE,'yyyy-MM-dd') = #{curveDate}

select CURVE_CODE id, CURVE_CODE || ':' || INT_CURVE_TYPE text, INT_CURVE_TYPE object from MST_CURVE_DEF
( CURVE_CODE LIKE CONCAT('%', CONCAT(#{search}, '%')) OR INT_CURVE_TYPE LIKE CONCAT('%', CONCAT(#{search}, '%')) )
and CURVE_CODE = #{initValue}
AND CURVE_TYPE = #{CURVE_CLASS}
